internal static class DofusAcceptance {
 internal const string Sample=@"{""data"":{""guide"":{""url"":""parcours-exemple"",""title"":""Parcours fictif de validation"",""description"":""<p>Données de test uniquement</p>"",""objectives"":[{""id"":1,""type"":""title"",""payload"":{""fr"":""Zone de test""}},{""id"":2,""type"":""note"",""payload"":{""fr"":""Point de test [-1,2]""}},{""id"":3,""type"":""quest"",""payload"":10},{""id"":4,""type"":""group"",""payload"":[{""id"":5,""type"":""quest"",""payload"":10}]},{""id"":6,""type"":""choice"",""payload"":[{""condition"":""Classe=Sacri"",""objectives"":[{""id"":7,""type"":""quest"",""payload"":11}]},{""condition"":""Classe=Iop"",""objectives"":[{""id"":8,""type"":""quest"",""payload"":12}]}]}]},""quests"":{""10"":{""name"":{""fr"":""Première quête fictive""},""dplnUrl"":""https://example.com/guide"",""prerequisites"":[{""type"":""quest"",""id"":11}],""objectives"":[{""type"":""note"",""payload"":{""fr"":""Instruction de test""}}],""items"":[{""count"":3,""item"":{""id"":500,""name"":{""fr"":""Ressource fictive""}}}]},""11"":{""name"":{""fr"":""Branche Sacrieur fictive""},""objectives"":[],""items"":[]},""12"":{""name"":{""fr"":""Branche Iop fictive""},""objectives"":[],""items"":[]}},""achievements"":{}}}";
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 internal static void Test(string folder){DofusInstructionsAcceptance.Test(folder);DofusVisualAcceptance.Test(folder);DofusTools.Test(folder);QuestCaptureImport.Test(folder);
  var store=new Store(Path.Combine(folder,"dofus"));var a=new DofusCharacter{id="a",name="A",classCode="Sacri",alignment="Bonta",order="CV",guide="parcours-exemple"};var b=new DofusCharacter{id="b",name="B",classCode="Iop",guide=a.guide};store.Value.dofus.characters.AddRange(new[]{a,b});store.Value.dofus.active=a.id;store.Save();var doc=TougliReader.Parse(Sample,a);Check(doc.Steps.Count==4&&doc.Steps[0].Coordinates=="-1,2"&&doc.Steps.Last().Title.Contains("Sacrieur"),"Guide et choix de classe");Check(doc.Steps[1].Details.Contains("Prérequis · Branche Sacrieur"),"Nom du prérequis");Check(TougliReader.Parse(Sample,b).Steps.Last().Title.Contains("Iop"),"Branche autre personnage");var unknown=TougliReader.Parse(Sample,new DofusCharacter());Check(!unknown.Steps.Last().CanComplete,"Choix non renseigné deviné");Check(DofusCompanion.Remaining(store.Value,doc).Single().Count==3,"Ressources répétées doublonnées");DofusCompanion.Navigate(store,doc,1,true);Check(DofusCompanion.Current(store.Value,doc).Title=="Première quête fictive"&&DofusCompanion.Find(store.Value,a).done.Count==1,"Valider et avancer");store.Value.dofus.active=b.id;store.Save();Check(DofusCompanion.Find(store.Value,b)==null,"Progression partagée entre personnages");store.Value.dofus.active=a.id;store.Save();var loaded=new Store(store.Root);Check(DofusCompanion.Current(loaded.Value,doc).Key==doc.Steps[1].Key,"Reprise après redémarrage");DofusCompanion.Navigate(store,doc,-1,false);DofusCompanion.Toggle(store,doc);Check(DofusCompanion.Find(store.Value,a).done.Count==0,"Annuler une validation");TougliReader.Cache(store,a.guide,Sample);bool bad=false;try{TougliReader.Parse("{}",a);}catch(InvalidDataException){bad=true;}Check(bad&&TougliReader.Cached(store,a.guide)==Sample,"Dernier guide préservé après format invalide");Check(!TougliReader.ValidSlug("../x")&&TougliReader.SafeUrl("file:///test")==""&&TougliReader.SafeUrl("javascript:alert(1)")=="","Chemin ou lien dangereux accepté");Check(TougliReader.Plain("<script>bad()</script><p>texte &amp; texte</p>")=="texte & texte","Texte HTML");
  string path=Path.Combine(store.Root,"state.json");File.Delete(path);Directory.CreateDirectory(path);bad=false;try{DofusCompanion.Navigate(store,doc,1,true);}catch(IOException){bad=true;}catch(UnauthorizedAccessException){bad=true;}Directory.Delete(path);Check(bad&&DofusCompanion.Find(store.Value,a).done.Count==0,"Retour après échec d’écriture");store.Save();var backup=Path.Combine(folder,"dofus.mespace");FullBackup.Export(store,backup);var target=new Store(Path.Combine(folder,"dofus-restore"));using(var plan=FullBackup.Prepare(target,backup))FullBackup.Commit(target,plan);Check(target.Value.dofus.characters.Count==2&&target.Value.dofus.progress.Count==1&&!Directory.Exists(Path.Combine(target.Root,"TougliCache")),"Sauvegarde progression sans redistribution des guides");var mode=new LaunchMode{name="Dofus",dofusView="both"};Check(LaunchModes.Clone(mode).dofusView=="both","Mode compagnon cloné");File.WriteAllText(Path.Combine(folder,"DOFUS_PASS.txt"),"PASS: real Tougli schema fixture, class choice, unresolved condition, prerequisites, resource deduplication, manual navigation/undo, independent characters, restart, failed-save rollback, HTML and URL safety, backup/restore and mode clone. No game automation or Tougli account sync.");
 }
 internal static int DownloadTest(string folder){try{Directory.CreateDirectory(folder);System.Net.ServicePointManager.SecurityProtocol|=System.Net.SecurityProtocolType.Tls12;using(var http=new System.Net.Http.HttpClient(new System.Net.Http.HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(45)}){var bytes=new ApplicationUpdates(http).Read(TougliReader.Api+"/api/guide/details/rsa-rush-sylvestre-accelere",TougliReader.MaxBytes,System.Threading.CancellationToken.None).GetAwaiter().GetResult();File.WriteAllBytes(Path.Combine(folder,"guide.json"),bytes);}return ReaderTest(folder);}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"DOWNLOAD_FAIL.txt"),ex.ToString());return 1;}}
 internal static int ReaderTest(string folder){try{var file=Path.Combine(folder,"guide.json");if(new FileInfo(file).Length>TougliReader.MaxBytes)throw new InvalidDataException("Guide trop volumineux");var json=File.ReadAllText(file);var document=TougliReader.Parse(json,new DofusCharacter{classCode="Sacri",alignment="Bonta",order="CV"});File.WriteAllText(Path.Combine(folder,"reader-result.json"),new JavaScriptSerializer().Serialize(new{slug=document.Slug,steps=document.Steps.Count,unresolved=document.Steps.Count(s=>!s.CanComplete),quests=document.Steps.Count(s=>s.QuestId!=null),resources=document.Steps.Sum(s=>s.Resources.Count)}));return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"READER_FAIL.txt"),ex.ToString());return 1;}}
}
