 }
 void usingOverlayTest(string folder,TougliDocument doc){var overlay=new DofusOverlay(owner,store,CurrentDofusDocument,()=>Go("Compagnon Dofus"),DofusStepAction,DofusToggle,CopyDofusTravel);try{overlay.Render(Path.Combine(folder,"Dofus-overlay.png"));if(!LogicalControls<Image>(overlay).Any(x=>x.Source is System.Windows.Media.Imaging.BitmapSource&&((System.Windows.Media.Imaging.BitmapSource)x.Source).PixelWidth==384)||!LogicalControls<Image>(overlay).Any(x=>x.Width==66&&x.Source is System.Windows.Media.Imaging.BitmapSource))throw new Exception("Portrait entier ou Dofus absent de l’overlay");var next=LogicalControls<Button>(overlay).First(b=>Convert.ToString(b.Content)=="Terminé →");next.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));overlay.RefreshView();if(DofusCompanion.Find(store.Value,DofusCompanion.Character(store.Value)).done.Count!=2)throw new Exception("Validation overlay");store.Value.settings.PrivacyMode=true;overlay.RefreshView();if(LogicalControls<TextBlock>(overlay).Any(t=>t.Text.Contains("Première quête fictive")))throw new Exception("Guide visible en mode discret");store.Value.settings.PrivacyMode=false;overlay.RefreshView();}finally{overlay.Close();store.Value.settings.PrivacyMode=false;}}
